use super::*;
#[test]
fn original_json_native_fixed2_derives_utf8_bytes_and_retires_partial_native_backing(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let g=&law["grant"];let n=|key:&str|g[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("maximumItems"),maximum_copy_bytes:n("maximumCopyBytes"),maximum_capacity_bytes:n("maximumCapacityBytes"),maximum_release_bytes:n("maximumReleaseBytes"),maximum_depth:n("maximumDepth")};let maximum=law["maximumTurns"].as_u64().unwrap();let l=&law["limits"];let limits=JsonReadLimits{maximum_bytes:l["maximumBytes"].as_u64().unwrap(),maximum_allocation_bytes:l["maximumAllocationBytes"].as_u64().unwrap()as usize,maximum_depth:l["maximumDepth"].as_u64().unwrap()as usize,maximum_items:l["maximumItems"].as_u64().unwrap()};
 for source in law["sources"].as_array().unwrap(){let source=source.as_str().unwrap();for cancelled in[0,1,5,12,maximum]{let mut cursor=JsonSourceCursor::<_,DslValue>::new(source,JsonMemberPolicy::Reject,limits).unwrap();let mut callback=|_|true;let mut control=semio_framework_value::NativeDecodeControl::new(limits.maximum_allocation_bytes,&mut callback);let(mut birth,mut release,mut copied)=(0,0,0);let mut output=None;
  for _ in 0..cancelled{let demand=cursor.normal_step_demands().unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if axis==2&&demand.copy_bytes==0||axis==3&&demand.capacity_bytes==0{continue}let(result,born,released)=test_allocation::observe_backing(||cursor.step(1,&mut control,denied));if axis==1{assert!(matches!(result,Err(JsonError::Native(error))if error.kind==ValueRefusalKind::DepthLimit))}else{assert!(result.unwrap().is_none())}assert_eq!((born,released),(0,0));assert_eq!(cursor.normal_step_progress(),Default::default())}
   let(result,born,released)=test_allocation::observe_backing(||cursor.step(1,&mut control,grant));let progress=cursor.normal_step_progress();assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));birth+=born;release+=released;copied+=progress.copied_bytes;if let Some(value)=result.unwrap(){output=Some(value);break}}
  if cancelled==maximum{let value=output.as_ref().expect("original fixed2 grammar must finish without increasing policy");let DslValue::String(text)=value else{panic!("original scalar JSON changed type")};assert_eq!(text,&serde_json::from_str::<String>(source).unwrap());assert_eq!(copied,text.len());}
  let(result,born,released)=test_allocation::observe_backing(||cursor.into_retirement(grant).map_err(|(error,_)|error));let(owner,progress)=result.unwrap();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));birth+=born;release+=released;let mut retirement=Some(owner);for _ in 0..maximum{if retirement.is_none(){break}let(result,born,released)=test_allocation::observe_backing(||semio_framework_value::close_factory_ticket(&mut retirement,grant));let progress=result.unwrap().progress();assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));birth+=born;release+=released;}assert!(retirement.is_none());if let Some(value)=output.take(){let(result,born,released)=test_allocation::observe_backing(||semio_framework_value::admit_owned_retirement(value,grant).map_err(|(error,_)|error));let(owner,progress)=result.unwrap();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));birth+=born;release+=released;let mut recipient=Some(owner);for _ in 0..maximum{if recipient.is_none(){break}let(result,born,released)=test_allocation::observe_backing(||semio_framework_value::close_factory_ticket(&mut recipient,grant));let progress=result.unwrap().progress();assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));birth+=born;release+=released;}assert!(recipient.is_none());}assert_eq!(birth,release);
 }}eprintln!("[DEBUG] Original JSON raw and surrogate-derived UTF8 finish under unchanged fixed2 copy authority; real partial native byte backing survives cancellation, exact physical receipts balance and terminalDrop0");
}
